/*
 * Focused regression harness for the ITS#10211 peercred uid/gid formatting fix.
 *
 * Mirrors the exact allocation and sprintf statement from
 * servers/slapd/daemon.c slap_listener() AF_LOCAL case.
 *
 *   mode 'd': unpatched behaviour  -> "gidNumber=%d+uidNumber=%d," with (int) casts
 *   mode 'u': patched behaviour    -> "gidNumber=%u+uidNumber=%u," with gid, uid
 *
 * Args: <d|u> <uid> <gid>
 */
#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>

#define STRLENOF(s) (sizeof(s) - 1)

int main(int argc, char **argv)
{
	size_t bufsz = STRLENOF("gidNumber=4294967295+uidNumber=4294967295,"
				"cn=peercred,cn=external,cn=auth") + 1;
	uid_t uid;
	gid_t gid;
	char *authid;
	int n;

	if (argc != 4) {
		fprintf(stderr, "usage: %s <d|u> <uid> <gid>\n", argv[0]);
		return 2;
	}
	uid = (uid_t)strtoul(argv[2], NULL, 10);
	gid = (gid_t)strtoul(argv[3], NULL, 10);
	authid = malloc(bufsz);
	if (!authid)
		return 2;

	if (argv[1][0] == 'd') {
		n = sprintf(authid, "gidNumber=%d+uidNumber=%d,"
			    "cn=peercred,cn=external,cn=auth",
			    (int) gid, (int) uid);
	} else if (argv[1][0] == 'u') {
		n = sprintf(authid, "gidNumber=%u+uidNumber=%u,"
			    "cn=peercred,cn=external,cn=auth",
			    gid, uid);
	} else {
		fprintf(stderr, "unknown mode %s\n", argv[1]);
		return 2;
	}

	printf("mode=%c alloc=%zu len=%d string=%s\n",
	       argv[1][0], bufsz, n, authid);
	free(authid);
	return 0;
}

